Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

constexpr int MAX_N = (1 << 19) + 5;
int N, K, MOD, MAX_VAL, BIT_COUNT[MAX_N], F[MAX_N];
int T1[20][MAX_N], T2[20][MAX_N], T3[20][MAX_N];
long long MOD_SQ;
long long TMP[20][MAX_N];
long long FACT[MAX_N], INV_FACT[MAX_N];

long long mod_exp(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

void init_factorials() {
    FACT[0] = 1;
    for (int i = 1; i <= MAX_VAL; ++i)
        FACT[i] = FACT[i-1] * i % MOD;
    INV_FACT[MAX_VAL] = mod_exp(FACT[MAX_VAL], MOD - 2);
    for (int i = MAX_VAL - 1; i >= 0; --i)
        INV_FACT[i] = INV_FACT[i+1] * (i+1) % MOD;
}

int ceil_pow2(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void fwht(int *arr, int len, bool inv = false) {
    static long long buf[MAX_N];
    for (int i = 0; i < len; ++i) buf[i] = arr[i];

    if (inv) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    buf[i + step + j] = (buf[i + step + j] - buf[i + j]) % MOD;
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    buf[i + step + j] = (buf[i + step + j] + buf[i + j]) % MOD;
                }
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        arr[i] = (int)(buf[i] % MOD);
        if (arr[i] < 0) arr[i] += MOD;
    }
}

inline void reduce(long long &x) {
    if (x >= MOD_SQ) x -= MOD_SQ;
}

void convolve() {
    for (int i = 0; i <= 19; ++i) {
        memset(T1[i], 0, sizeof(int[MAX_VAL + 1]));
        memset(TMP[i], 0, sizeof(long long[MAX_VAL + 1]));
    }

    for (int i = 0; i <= MAX_VAL; ++i)
        T1[BIT_COUNT[i]][i] = F[i];

    for (int i = 0; i <= 19; ++i)
        fwht(T1[i], MAX_VAL + 1);

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                reduce(TMP[i + j][idx] += 1LL * T1[i][idx] * T2[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            T3[i][idx] = (int)(TMP[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht(T3[i], MAX_VAL + 1, true);

    for (int i = 0; i <= MAX_VAL; ++i)
        F[i] = T3[BIT_COUNT[i]][i];
}

void square() {
    static int buf[20][MAX_N];
    for (int i = 0; i <= 19; ++i)
        memset(TMP[i], 0, sizeof(long long[MAX_VAL + 1]));

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                reduce(TMP[i + j][idx] += 1LL * T2[i][idx] * T2[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            buf[i][idx] = (int)(TMP[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht(buf[i], MAX_VAL + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(T2[i], 0, sizeof(int[MAX_VAL + 1]));

    for (int idx = 0; idx <= MAX_VAL; ++idx)
        T2[BIT_COUNT[idx]][idx] = buf[BIT_COUNT[idx]][idx];

    for (int i = 0; i <= 19; ++i)
        fwht(T2[i], MAX_VAL + 1);
}

int main() {
    scanf("%d%d%d", &N, &K, &MOD);
    MOD_SQ = 1LL * MOD * MOD;

    if (N & 1) {
        printf("%lld", mod_exp(K, N));
        return 0;
    }

    F[0] = 1;
    MAX_VAL = ceil_pow2(N + 1) - 1;
    init_factorials();

    for (int i = 0; i <= MAX_VAL; ++i)
        BIT_COUNT[i] = __builtin_popcount(i);

    for (int i = 0; i <= MAX_VAL; ++i)
        T2[BIT_COUNT[i]][i] = INV_FACT[i];

    for (int i = 0; i <= 19; ++i)
        fwht(T2[i], MAX_VAL + 1);

    int orig_k = K;
    while (K) {
        if (K & 1) convolve();
        K >>= 1;
        if (K) square();
    }

    long long ans = (mod_exp(orig_k, N) - FACT[N] * F[N] % MOD + MOD) % MOD;
    printf("%lld", ans);
    return 0;
}
